#!/bin/bash

sort() {
    local n=${#arr[@]}
    local j tmp
    for (( j = 0; j < n; j++ )); do
        minidx "$j"                 # sets the global variable idx
        tmp=${arr[j]}
        arr[j]=${arr[idx]}
        arr[idx]=$tmp
    done
}

minidx() {
    local start=$1
    local n=${#arr[@]}
    local i
    idx=$start                      # result returned in the global idx
    for (( i = start + 1; i < n; i++ )); do
        if (( arr[i] < arr[idx] )); then
            idx=$i
        fi
    done
}

# places the command line arguments into arr and calls sort
arr=("$@")
sort

# print the sorted elements of arr on a single line after this comment
echo "${arr[@]}"
```

Tested: `./sort.sh 0 3 1 4 2` prints `0 1 2 3 4`; `./sort.sh 5 -3 10 -3 0 7` prints `-3 -3 0 5 7 10`.
